173	  }
174	  if (output === undefined || output === '') {
175	    process.stderr.write('perf-regress: --output 不能为空\n');
176	    return EXIT_USAGE;
177	  }
178	
179	  const runsR = parsePositiveIntOption(values, 'runs', { min: 1, required: true });
180	  if (runsR.error) {
