'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');
const { round6 } = require('./stats');
const { parseArgs, EXIT_OK, EXIT_USAGE, EXIT_OUTPUT_ERROR } = require('./collect');
const {
  loadInput,
  parseNumberOption,
  computeComparison,
  decideFromPValue,
  buildAttribution,
  DEFAULT_ALPHA,
  DEFAULT_MIN_CHANGE_PERCENT,
} = require('./compare');

const KNOWN_KEYS = new Set(['manifest', 'output', 'alpha', 'min-change-percent']);

function fail(message) {
  process.stderr.write(`perf-regress: ${message}\n`);
  return EXIT_USAGE;
}

// Benjamini-Hochberg: ...
function adjustPValues(pValues) {
  const m = pValues.length;
  const order = pValues.map((p, i) => [p, i]).sort((a, b) => a[0] - b[0]);
  const adjusted = new Array(m);
  let best = 1; // running min of m*p_(j)/j from the tail
  for (let rank = m; rank >= 1; rank--) {
    const [p, idx] = order[rank - 1];
    const q = Math.min(1, (m * p) / rank);
    best = Math.min(best, q);
    adjusted[idx] = round6(best);
  }
  return adjusted;
}
```

Wait — q_i = min(1, min over j>=i (m*p_j/j)). Iterating from largest rank down, best = min over j>=i. Yes.

