  }
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
    return fail('manifest 结构无效: 顶层须为对象');
  }
  if (!Array.isArray(manifest.cases) || manifest.cases.length === 0) {
    return fail('manifest 的 cases 须为非空数组');
  }
  const manifestDir = path.dirname(manifestPath);
  const seen = new Set();
  const caseDefs = [];
  for (let i = 0; i < manifest.cases.length; i++) {
    const c = manifest.cases[i];
    const label = `cases[${i}]`;
    if (!c || typeof c !== 'object' || Array.isArray(c)) {
      return fail(`manifest ${label} 须为对象`);
    }
    if (typeof c.name !== 'string' || c.name === '') {
      return fail(`manifest ${label} 的 name 须为非空字符串`);
    }
    if (seen.has(c.name)) {
      return fail(`manifest case 名称重复: ${c.name}`);
    }
    seen.add(c.name);
    if (typeof c.baseline !== 'string' || c.baseline === '') {
      return fail(`manifest case ${c.name} 的 baseline 须为非空字符串`);
    }
    if (typeof c.candidate !== 'string' || c.candidate === '') {
      return fail(`manifest case ${c.name} 的 candidate 须为非空字符串`);
    }
    caseDefs.push({
      name: c.name,
      baseline: path.resolve(manifestDir, c.baseline),
      candidate: path.resolve(manifestDir, c.candidate),
    });
  }

  const cases = [];
  for (const def of caseDefs) {
    const baseline = await loadInput(def.baseline, `case ${def.name} 的 baseline`);
    if (baseline.error) return fail(baseline.error);
    const candidate = await loadInput(def.candidate, `case ${def.name} 的 candidate`);
    if (candidate.error) return fail(candidate.error);
    if (baseline.command !== candidate.command) {
      return fail(`case ${def.name} 的两份输入 command 不一致`);
    }
    cases.push({ def, baseline, candidate });
  }

  const comparisons = cases.map(({ baseline, candidate }) =>
    computeComparison(baseline, candidate, alpha, minChangePercent));
  const adjusted = adjustPValues(comparisons.map((c) => c.welch.p_value));

  const outCases = cases.map(({ def, baseline }, i) => {
    const comparison = comparisons[i];
    const adjustedP = adjusted[i];
    const decision = decideFromPValue(adjustedP, alpha, comparison.delta.mean.percent, minChangePercent);
    return {
      name: def.name,
      command: baseline.command,
      ...comparison,
      decision,
