test('decision 以 adjusted_p_value 判定：校正后不显著则 not_significant', () => {
  const dir = tempDir();
  // 同一对样本复制 4 次：原始 p≈0.066 > 0.05 已不显著，校正后更大
  const durationsB = [100, 102, 98, 101, 99, 100, 103, 97];
  const durationsC = [102, 104, 100, 103, 101, 102, 105, 99];
  const cases = [];
  for (let i = 0; i < 4; i++) {
    cases.push({
      name: `case-${i}`,
      baseline: writeCollect(dir, `b${i}.json`, durationsB),
      candidate: writeCollect(dir, `c${i}.json`, durationsC),
    });
  }
  const manifest = writeManifest(dir, cases);
  const out = path.join(dir, 'out.json');
  const r = runCli(['--manifest', manifest, '--output', out]);
  assert.equal(r.status, 0, r.stderr);

  const result = readJson(out);
  // m=4，p 相同：q = min(1, 4*p/1) = 4p（p≈0.066 -> ≈0.264）
  const p = result.cases[0].welch.p_value;
  const expected = Math.round(Math.min(1, 4 * p) * 1e6) / 1e6;
  for (const c of result.cases) {
    assert.equal(c.adjusted_p_value, expected);
    assert.equal(c.decision, 'not_significant');
  }
  assert.equal(result.suite_summary.suite_decision, 'not_significant');
});

